var AjaxCheckDateSI = Class.create();
AjaxCheckDateSI.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    checkUserRequest: function() {
        var checkDate = this.getParameter('sysparm_date');
        if (!checkDate) {
            gs.error('No date provided');
            return 'Invalid input';
        }

        gs.info('Received date: ' + checkDate);

        var requests = [];
        var grAjaxCheckDateSI = new GlideRecord('x_1488662_rsvp_t_0_training_schedules');
        grAjaxCheckDateSI.addActiveQuery();
        grAjaxCheckDateSI.addQuery('training_day', '=', checkDate); // Exact match for date
        grAjaxCheckDateSI.query();

        while (grAjaxCheckDateSI.next()) {
            requests.push(grAjaxCheckDateSI.number.toString()); // Collect 'number' field
        }

        return requests.length > 0 ? requests.join(',') : 'none';
    },

    type: 'AjaxCheckDateSI'
});
